function maxXorPair(values) {
  let best = 0
  for (let bit = 29; bit >= 0; bit--) {
    best <<= 1
    const candidate = best | 1
    const prefixes = new Set(values.map(value => value >> bit))
    for (const prefix of prefixes) {
      if (prefixes.has(prefix ^ candidate)) {
        best = candidate
        break
      }
    }
  }
  return best
}

