def max_xor_pair(values):
    best = 0
    for bit in range(29, -1, -1):
        best <<= 1
        candidate = best | 1
        prefixes = {value >> bit for value in values}
        if any(prefix ^ candidate in prefixes for prefix in prefixes):
            best = candidate
    return best
